        "title": "Educational Assessment: Its Types and Outcomes: A Bibliometric Analytical Study",
        "authors": [
          "Abdul Ghani bin Md Din",
          "Mohd Azizul Rahman bin Zabidin",
          "Abdel Rahman Moawad Ali Tahawi",
          "Omar bin Md Din",
          "Fareed Aawi"
        ],
        "openAccessInfo": {
          "license": "CCBY",
          "status": "GOLD",
          "disclaimer": "Notice: This snippet is extracted from the open access paper or abstract available at https://api.unpaywall.org/v2/10.6007/ijarbss/v13-i11/19516?email=<INSERT_YOUR_EMAIL> or https://doi.org/10.6007/ijarbss/v13-i11/19516, which is subject to the license by the author or copyright owner provided with this content. Please go to the source to verify the license and copyright information for your use."
        }
