      "paper": {
        "corpusId": "270414273",
        "title": "Fostering Effective Teaching Practices: Integrating Formative Assessment and Mentorship in Indonesian Preservice Teacher Education",
        "authors": [
          "E. Prastikawati",
          "M. A. Adeoye",
          "John Ryan"
        ],
        "openAccessInfo": {
